insert into site_sections (key, eyebrow, title, description, image_url, image_alt, visible) values
  ('personalizacion', 'Cómo personalizamos', 'Un nombre, un hilo, una pieza única.', 'Escoges la pieza, el color de hilo y la tipografía del monograma. Digitalizamos el diseño en nuestro taller y lo bordamos punto por punto — no es impresión ni parche prefabricado.', null, '', true),
  ('coleccion-permanente', 'Colección permanente', 'Piezas que se bordan, no se fabrican.', 'Ajuar y accesorios para bebé hechos a mano, con bordado propio y algodones de primera. Cada pieza lleva el nombre de quien la va a usar.', null, '', true);
